'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { RotateCcwIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';

import {
  NOTICES,
  SOURCES,
  TEAM_NAME,
  WORKING_DURATION_MS,
  type Source,
  type SourceId,
} from './data';
import { fadePresence, Swap } from './motion-parts';
import { Notice, type NoticePhase } from './notice';

const SOURCES_ANCHOR = 'sources';

type Phases = Record<string, NoticePhase>;

function phaseOf(phases: Phases, noticeId: string): NoticePhase {
  return phases[noticeId] ?? 'open';
}

function isSourceResolved(phases: Phases, sourceId: SourceId) {
  const notice = NOTICES.find((item) => item.sourceId === sourceId);
  if (!notice) {
    return false;
  }
  return phaseOf(phases, notice.id) === 'resolved';
}

function sourceStateOf(source: Source, isResolved: boolean) {
  if (isResolved) {
    return source.resolved;
  }
  return source.open;
}

export default function Notifications03() {
  const [dismissedIds, setDismissedIds] = useState<string[]>([]);
  const [phases, setPhases] = useState<Phases>({});
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const shownNotices = NOTICES.filter(
    (notice) => !dismissedIds.includes(notice.id)
  );
  const hasNotices = shownNotices.length > 0;

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  function setPhase(noticeId: string, phase: NoticePhase) {
    setPhases((current) => ({ ...current, [noticeId]: phase }));
  }

  function act(noticeId: string) {
    setPhase(noticeId, 'working');
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      setPhase(noticeId, 'resolved');
    }, WORKING_DURATION_MS);
    timers.current.add(timer);
  }

  function dismiss(noticeId: string) {
    setDismissedIds((current) => [...current, noticeId]);
  }

  function showDismissed() {
    setDismissedIds([]);
  }

  return (
    <div className='bg-background text-foreground min-h-svh px-4 py-8 sm:px-8 sm:py-10'>
      <div className='mx-auto max-w-2xl'>
        <h1 className='text-2xl font-semibold text-balance'>
          Imports and sync
        </h1>
        <p className='text-muted-foreground mt-1 text-[13px]'>
          Where {TEAM_NAME} gets its members and its calendar
        </p>
        <div className='relative mt-6'>
          <AnimatePresence mode='popLayout' initial={false}>
            {hasNotices && (
              <motion.ul
                key='notices'
                aria-label='Notices'
                aria-live='polite'
                {...fadePresence()}
              >
                <AnimatePresence initial={false}>
                  {shownNotices.map((notice) => (
                    <Notice
                      key={notice.id}
                      notice={notice}
                      phase={phaseOf(phases, notice.id)}
                      recoveryHref={`#${SOURCES_ANCHOR}`}
                      onAction={act}
                      onDismiss={dismiss}
                    />
                  ))}
                </AnimatePresence>
              </motion.ul>
            )}
            {!hasNotices && (
              <motion.div
                key='no-notices'
                {...fadePresence()}
                className='flex flex-wrap items-center justify-between gap-2 pb-3'
              >
                <p className='text-muted-foreground text-[13px]'>
                  No notices, a source that needs you will show one here
                </p>
                <Button
                  variant='ghost'
                  size='sm'
                  onClick={showDismissed}
                  className='text-muted-foreground'
                >
                  <RotateCcwIcon />
                  Show dismissed notices
                </Button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
        <section id={SOURCES_ANCHOR} className='mt-7 scroll-mt-6'>
          <h2 className='text-sm font-medium'>Sources</h2>
          <ul className='bg-card hairline-ring ring-border hairline-divide-y divide-border mt-3 overflow-clip rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
            {SOURCES.map((source) => {
              const isResolved = isSourceResolved(phases, source.id);
              const state = sourceStateOf(source, isResolved);
              return (
                <li
                  key={source.id}
                  className='flex min-h-14 items-center justify-between gap-3 px-4 py-3'
                >
                  <div className='min-w-0'>
                    <p className='truncate text-[13px] font-medium'>
                      {source.name}
                    </p>
                    <p className='text-muted-foreground truncate text-xs'>
                      {source.detail}
                    </p>
                  </div>
                  <Swap swapKey={state.label}>
                    <Badge variant={state.variant}>{state.label}</Badge>
                  </Swap>
                </li>
              );
            })}
          </ul>
        </section>
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { LoaderIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { StatusOrb, type StatusOrbTone } from '@/registry/ndeko/ui/status-orb';

import type { NoticeData, NoticeTone } from './data';
import { fadePresence, heightPresenceOf, MorphText } from './motion-parts';

export type NoticePhase = 'open' | 'working' | 'resolved';

const ORB_TONE: Record<NoticeTone, StatusOrbTone> = {
  warning: 'warning',
  error: 'error',
  info: 'info',
};

function orbToneOf(tone: NoticeTone, phase: NoticePhase): StatusOrbTone {
  if (phase === 'resolved') {
    return 'success';
  }
  return ORB_TONE[tone];
}

function textOf(notice: NoticeData, isResolved: boolean) {
  if (isResolved) {
    return notice.resolved;
  }
  return notice.open;
}

function actionLabelOf(notice: NoticeData, isWorking: boolean) {
  if (isWorking) {
    return notice.workingAction;
  }
  return notice.action;
}

type NoticeProps = {
  notice: NoticeData;
  phase: NoticePhase;
  recoveryHref: string;
  onAction: (noticeId: string) => void;
  onDismiss: (noticeId: string) => void;
};

export function Notice({
  notice,
  phase,
  recoveryHref,
  onAction,
  onDismiss,
}: NoticeProps) {
  const shouldReduceMotion = useReducedMotion();
  const isResolved = phase === 'resolved';
  const isWorking = phase === 'working';
  const text = textOf(notice, isResolved);

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <div className='pb-3'>
        <div className='bg-card hairline-ring ring-border flex items-start gap-3 rounded-xl py-3 ps-3.5 pe-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
          <StatusOrb
            tone={orbToneOf(notice.tone, phase)}
            size='sm'
            className='mt-px'
          />
          <AnimatedSize className='min-w-0 flex-1'>
            <div className='relative'>
              <AnimatePresence mode='popLayout' initial={false}>
                <motion.div key={String(isResolved)} {...fadePresence()}>
                  <p className='text-[13px] font-medium'>{text.title}</p>
                  <p className='text-muted-foreground mt-0.5 text-[13px] text-pretty'>
                    {text.line}
                  </p>
                </motion.div>
              </AnimatePresence>
            </div>
            {!isResolved && (
              <div className='mt-3 flex flex-wrap items-center gap-x-4 gap-y-2'>
                <Button
                  size='sm'
                  variant='outline'
                  disabled={isWorking}
                  onClick={() => onAction(notice.id)}
                >
                  <AnimatedSize axis='width'>
                    <span className='flex items-center gap-1.5'>
                      {isWorking && (
                        <LoaderIcon className='size-3.5 animate-spin' />
                      )}
                      <MorphText text={actionLabelOf(notice, isWorking)} />
                    </span>
                  </AnimatedSize>
                </Button>
                <a
                  href={recoveryHref}
                  className='text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 rounded-sm text-xs underline-offset-4 outline-none hover:underline focus-visible:ring-[3px]'
                >
                  {notice.recoveryLink}
                </a>
              </div>
            )}
          </AnimatedSize>
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label={`Dismiss: ${text.title}`}
            onClick={() => onDismiss(notice.id)}
            className='text-muted-foreground -mt-0.5'
          >
            <XIcon />
          </Button>
        </div>
      </div>
    </motion.li>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={variants}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex items-center gap-[inherit]'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export function MorphText({ text }: { text: string }) {
  return <Swap swapKey={text}>{text}</Swap>;
}

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export function fadePresence() {
  return FADE_PRESENCE;
}

export type NoticeTone = 'warning' | 'error' | 'info';

export type SourceId = 'calendar' | 'import' | 'invites';

export type NoticeText = {
  title: string;
  line: string;
};

export type NoticeData = {
  id: string;
  sourceId: SourceId;
  tone: NoticeTone;
  open: NoticeText;
  resolved: NoticeText;
  action: string;
  workingAction: string;
  recoveryLink: string;
};

export type SourceState = {
  label: string;
  variant: 'success' | 'warning' | 'info' | 'destructive';
};

export type Source = {
  id: SourceId;
  name: string;
  detail: string;
  open: SourceState;
  resolved: SourceState;
};

